def short(n,k,s,a,d):
 return {'id':f'{sub}-i{n:02d}','kcs':[k],'kind':'short','difficulty':d,'command_word':s.split()[0],'source':{'type':'generated'},'stem':s,'marks':1,'rubric':[{'point':a,'keywords':[[a]]}],'explanation':a,'hints':['Identify the class or representation involved.','Use the relevant definition or naming rule.','Start by locating the atoms or group named in the question.']}
