# Every arithmetic/formula result is checked from the structural counts before insertion.
def empirical(counts):
 g=0
 for v in counts.values():g=gcd(g,v)
 return {k:v//g for k,v in counts.items()}
assert empirical({'C':6,'H':12,'O':6})=={'C':1,'H':2,'O':1}
assert empirical({'C':4,'H':8,'O':2})=={'C':2,'H':4,'O':1}
assert empirical({'C':3,'H':6,'O':2})=={'C':3,'H':6,'O':2}
